const BY_ID = new Map(SOURCES.map((s) => [s.id, s]));
export const getSource = (id: string) => BY_ID.get(id);
export const sourcesForDataset = (dataset: string) => SOURCES.filter((s) => s.datasets?.includes(dataset));
